from textual.app import ComposeResult, App
from textual.containers import Container
from textual.message import Message
from textual.widgets import Button, Label


class CustomWidget(Container):
    class ButtonPressed(Message):
        """Custom message when button is pressed."""
        def __init__(self, label: str):
            self.label = label
            super().__init__()

    def compose(self) -> ComposeResult:
        yield Button("Click Me", id="test_button")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        self.post_message(self.ButtonPressed("Button was clicked!"))


class MyApp(App):
    def compose(self) -> ComposeResult:
        yield Label("Waiting for message...", id="output")
        yield CustomWidget()

    def on_custom_widget_button_pressed(self, message: CustomWidget.ButtonPressed) -> None:
        self.query_one("#output", Label).update(message.label)


if __name__ == "__main__":
    app = MyApp()
    app.run()

